def sample_package(spec, doc_id, page, locations=None):
    questions = [dict(id=f"q{i+1}", type="objective", question=q[0], options=q[1], correct_index=q[2],
                      solution=q[3], topic=spec["topics"][min(i, len(spec["topics"])-1)], difficulty="Core")
                 for i,q in enumerate(spec["questions"])]
    questions.append(dict(id="q5", type="subjective", question=spec["subjective"][0], options=[],
                          correct_index=-1, solution=spec["subjective"][1], topic=spec["topics"][0], difficulty="Apply"))
    return dict(overview=spec["overview"], objectives=["Explain " + t.lower() for t in spec["topics"]],
                sections=[dict(title=s[0], body=s[1], kind=s[2], sources=[dict(doc_id=doc_id, page=p) for p in (locations or {}).get(s[0], [page])]) for s in spec["sections"]],
                diagrams=[dict(title="The process, at a glance", nodes=spec["diagram"])],
                questions=questions, flashcards=[dict(front=q[0], back=q[1][q[2]] + ". " + q[3]) for q in spec["questions"]],
                coverage_notes="", source_pages=[dict(doc_id=doc_id, page=page)])


def seed_sample(store):
    if any(c.get("demo") for c in store.courses()):
        return
    folder = Path(__file__).parent / "sample_sources"
    if not (folder / "Course-notes.pdf").exists():
        return
    course = store.create("Data Structures & Algorithms", "From the way data is stored to the way problems are solved. Six connected modules, one clear path.", demo=True)
    notes = store.add_pdf(course["id"], "Course-notes.pdf", "material", (folder / "Course-notes.pdf").read_bytes())
    store.add_pdf(course["id"], "Course-outline.pdf", "syllabus", (folder / "Course-outline.pdf").read_bytes())
    exam = store.add_pdf(course["id"], "Illustrative-exam.pdf", "pyq", (folder / "Illustrative-exam.pdf").read_bytes())
    locations = json.loads((folder / "locations.json").read_text("utf-8"))
    for i,spec in enumerate(SPECS):
        module = {key: spec[key] for key in ("id", "title", "description", "topics", "prerequisites")}
        module["package"] = sample_package(spec, notes["id"], i+1, locations[spec["id"]])
        course["modules"].append(module)
        course["pyqs"].append(dict(id=f"sample{i}", question=spec["subjective"][0], module_ids=[spec["id"]],
                                   year="Sample paper", number=str(i+1), marks="5", solution=spec["subjective"][1],
                                   doc_id=exam["id"], page=1, generated_solution=True))
    course.update(status="ready", pyq_batches=[exam["id"] + ":1"])
    store.save(course)
